package com.abhishek.ecommerce.product;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;@Entity public class Product{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false,unique=true)String sku;@Column(nullable=false)String name;String category;BigDecimal price;int stock;boolean active=true;public UUID getId(){return id;}public String getSku(){return sku;}public void setSku(String v){sku=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public int getStock(){return stock;}public void setStock(int v){stock=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}